.sw{width:22px;height:8px;border-radius:5px;flex:none;position:relative}
.sw.room{background:radial-gradient(circle at 25% 50%,var(--room) 0 2.5px,transparent 3px),radial-gradient(circle at 60% 50%,var(--room) 0 2px,transparent 2.5px),radial-gradient(circle at 90% 50%,var(--room) 0 1.5px,transparent 2px)}
.sw.out{background:radial-gradient(circle at 25% 50%,var(--out) 0 2.5px,transparent 3px),radial-gradient(circle at 60% 50%,var(--out) 0 2px,transparent 2.5px),radial-gradient(circle at 90% 50%,var(--out) 0 1.5px,transparent 2px)}
.sw.ref{background:linear-gradient(90deg,#2156ff,#2fd0ff,#f2e6c9,#ffb03a,#ff3a1e);height:6px;box-shadow:0 0 10px rgba(255,120,60,.25)}
.sw.heat{width:14px;height:14px;margin:0 4px;border-radius:50%;background:radial-gradient(circle,#ffd29a 0 18%,rgba(255,138,61,.9) 30%,rgba(255,138,61,0) 70%);box-shadow:0 0 0 1.5px rgba(255,138,61,.55)}
.sw.water{width:9px;height:12px;margin:0 6.5px;border-radius:50% 50% 50% 50%/60% 60% 40% 40%;background:linear-gradient(180deg,#d6f1ff,#5fb8ff)}

/* caption */
#caption{left:50%;bottom:24px;transform:translateX(-50%);width:min(460px,calc(100vw - 560px));min-width:320px;padding:12px 16px 12px;transition:opacity .35s}
.cap-k{display:flex;align-items:center;gap:8px;font-size:10.5px;text-transform:uppercase;letter-spacing:.14em;color:var(--mute)}
.cap-k .pulse{width:6px;height:6px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 0 var(--accent);animation:pulse 2s infinite}
@keyframes pulse{0%{box-shadow:0 0 0 0 color-mix(in srgb,var(--accent) 60%,transparent)}100%{box-shadow:0 0 0 8px transparent}}
.cap-k #capStep{margin-left:auto;font-family:var(--mono);letter-spacing:.04em}
#capTitle{font-size:14.5px;font-weight:600;margin:6px 0 3px;letter-spacing:-.005em}
#capText{margin:0;font-size:13px;line-height:1.5;color:#c3ccd8;min-height:2.9em}
.cap-nav{display:none;align-items:center;gap:8px;margin-top:10px}
body.touring .cap-nav{display:flex}
.cap-nav button{appearance:none;border:1px solid var(--line);background:rgba(255,255,255,.05);color:var(--text);font:inherit;font-size:12px;border-radius:9px;min-width:36px;height:32px;padding:0 10px;cursor:pointer}
.cap-nav button:hover{background:rgba(255,255,255,.1)}
.cap-nav .bar{flex:1;height:3px;border-radius:2px;background:rgba(255,255,255,.08);overflow:hidden}
.cap-nav .bar i{display:block;height:100%;width:0;background:var(--accent);border-radius:2px}

