.anc{width:0;height:0;position:relative}
.anc::before{content:'';position:absolute;left:-3.5px;top:-3.5px;width:7px;height:7px;border-radius:50%;background:#fff;box-shadow:0 0 0 3px rgba(255,255,255,.14),0 0 10px rgba(255,255,255,.4)}
.anc.nodot::before{display:none}
.tag{position:absolute;white-space:nowrap;font-size:11px;font-weight:540;letter-spacing:.01em;color:#eef3f9;padding:4px 9px;border-radius:999px;background:rgba(10,14,20,.74);border:1px solid rgba(255,255,255,.14);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);transition:opacity .35s,border-color .35s,box-shadow .35s,background .35s}
.tag::before{content:'';position:absolute;background:rgba(255,255,255,.45)}
.tag.r{left:20px;top:0;transform:translateY(-50%)}
.tag.r::before{right:100%;top:50%;width:17px;height:1px}
.tag.l{right:20px;top:0;transform:translateY(-50%)}
.tag.l::before{left:100%;top:50%;width:17px;height:1px}
.tag.u{bottom:20px;left:0;transform:translateX(-50%)}
.tag.u::before{top:100%;left:50%;width:1px;height:17px}
.tag.d{top:20px;left:0;transform:translateX(-50%)}
.tag.d::before{bottom:100%;left:50%;width:1px;height:17px}
