body.focusing .tag:not(.hl):not(.zone){opacity:.28}
.tag.badge{font-size:10.5px;text-transform:uppercase;letter-spacing:.1em;font-weight:620;padding:5px 10px 5px 8px;display:flex;align-items:center;gap:6px}
.tag.badge::before{display:none}
.tag.badge svg{width:12px;height:12px}
.tag.badge.abs{color:#bfe0ff;border-color:rgba(47,140,255,.6);background:rgba(8,26,52,.78);box-shadow:0 0 18px rgba(47,140,255,.25)}
.tag.badge.rel{color:#ffd9bf;border-color:rgba(255,106,31,.6);background:rgba(52,20,6,.78);box-shadow:0 0 18px rgba(255,106,31,.25)}
.tag.zone{background:transparent;border:0;-webkit-backdrop-filter:none;backdrop-filter:none;padding:0;text-align:center;transform:translate(-50%,-50%);left:0;top:0}
.tag.zone::before{display:none}
.tag.zone small{display:block;font-size:10px;letter-spacing:.28em;text-transform:uppercase;color:rgba(255,255,255,.55);font-weight:600}
.tag.zone b{display:block;font-family:var(--mono);font-size:20px;font-weight:400;color:rgba(255,255,255,.9);text-shadow:0 2px 14px rgba(0,0,0,.6)}
.hide-labels #labels{display:none}

/* loader / fallback */
#loader{position:fixed;inset:0;display:grid;place-items:center;z-index:20;background:#07090c;transition:opacity .6s}
#loader span{font-size:12px;letter-spacing:.2em;text-transform:uppercase;color:var(--mute)}
#loader.done{opacity:0;pointer-events:none}
#fallback{position:fixed;inset:0;z-index:30;display:grid;place-items:center;padding:24px;background:radial-gradient(ellipse at 50% 30%,#141b26,#07090c)}
#fallback[hidden]{display:none}
#fallback div{max-width:440px;text-align:center}
#fallback p{color:#c3ccd8;line-height:1.55;font-size:14px}
#fallback .diag{font-size:13px;color:var(--mute);text-align:left;margin-top:18px;padding:14px 16px;border:1px solid var(--line);border-radius:12px}

/* responsive */
@media (max-width:1100px){#caption{width:min(420px,calc(100vw - 360px))}#legend{display:none}.row .mobile-only{display:flex}body.show-legend #legend{display:grid}}
