  .temps b{font-size:16px}
  .temps .trend{display:none}
  .flows{grid-column:1/-1;gap:3px}
  .flows>div{font-size:11px}
  .flows dt{flex-basis:92px}
  .st-note{display:none}
  #controls{top:auto;right:10px;left:10px;bottom:calc(10px + env(safe-area-inset-bottom));width:auto;padding:8px;gap:6px}
