  body.show-legend #caption{opacity:0;pointer-events:none}
  .tag{font-size:10px;padding:3px 7px}
  .tag.zone b{font-size:15px}
}
@media (max-width:760px) and (max-height:560px){#status .flows{display:none}}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
